    "src": "html, body { margin: 0; height: 100%; background: #e3ece4; overflow: hidden; }\ncanvas { display: block; width: 100vw; height: 100vh; }\n#alone { position: absolute; inset: 0; margin: auto; height: fit-content; max-width: 26em; padding: 1em;\n  font: 15px/1.45 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; color: #1f3329; text-align: center; }\n",
